"use server";
import { redirect } from "next/navigation";
import { revalidatePath } from "next/cache";
import { getBooks, saveBooks, makeId, type Book } from "@/lib/books";

export async function addBook(formData: FormData) {
  const title = String(formData.get("title") || "").trim();
  const author = String(formData.get("author") || "").trim();
  const notes = String(formData.get("notes") || "").trim();
  if (!title || !author) return;
  const books = await getBooks();
  const book: Book = {
    id: makeId(),
    title,
    author,
    notes,
    status: "reading",
    createdAt: new Date().toISOString(),
  };
  books.unshift(book);
  await saveBooks(books);
  revalidatePath("/");
  redirect("/");
}

export async function markFinished(formData: FormData) {
  const id = String(formData.get("id") || "");
  if (!id) return;
  const books = await getBooks();
  const idx = books.findIndex((b) => b.id === id);
  if (idx === -1) return;
  books[idx].status = "finished";
  await saveBooks(books);
  revalidatePath("/");
  revalidatePath(`/books/${id}`);
}

export async function markReading(formData: FormData) {
  const id = String(formData.get("id") || "");
  if (!id) return;
  const books = await getBooks();
  const idx = books.findIndex((b) => b.id === id);
  if (idx === -1) return;
  books[idx].status = "reading";
  await saveBooks(books);
  revalidatePath("/");
  revalidatePath(`/books/${id}`);
}

