        <h2 style={{ margin: 0, fontSize: 16, fontWeight: 650 }}>Add a book</h2>
        <button
          onClick={() => setOpen((v) => !v)}
          aria-expanded={open}
          style={{ background: open ? "#f3efe8" : "#1a1a1a", color: open ? "#1a1a1a" : "#fff", border: open ? "1px solid #e5e0d5" : "1px solid #1a1a1a", borderRadius: 999, padding: "7px 14px", cursor: "pointer", fontSize: 13, fontWeight: 600 }}
        >
          {open ? "Close" : "+ Add book"}
        </button>
      </div>
      {open && (
        <form action={addBook} style={{ marginTop: 16, display: "grid", gap: 12 }}>
          <label style={{ display: "grid", gap: 6, fontSize: 13, fontWeight: 600 }}>
            Title *
            <input name="title" required placeholder="e.g. The Old Man and the Sea" style={inputStyle} />
          </label>
          <label style={{ display: "grid", gap: 6, fontSize: 13, fontWeight: 600 }}>
            Author *
            <input name="author" required placeholder="e.g. Ernest Hemingway" style={inputStyle} />
          </label>
          <label style={{ display: "grid", gap: 6, fontSize: 13, fontWeight: 600 }}>
            Notes
            <textarea name="notes" rows={3} placeholder="What you liked, thoughts, page progress..." style={{ ...inputStyle, resize: "vertical" as const }} />
          </label>
          <button type="submit" style={{ background: "#1a1a1a", color: "#fff", border: "1px solid #1a1a1a", borderRadius: 10, padding: "10px 14px", cursor: "pointer", fontWeight: 650, fontSize: 14 }}>
            Save book
          </button>
        </form>
      )}
    </div>
  );
}

