import { getBooks } from "@/lib/books";
import AddBookForm from "@/components/AddBookForm";
import { markFinished } from "@/app/actions";

export const dynamic = "force-dynamic";

function BookCard({ book, action }: { book: { id: string; title: string; author: string; notes: string; status: string }; action?: React.ReactNode }) {
  return (
    <div style={{ background: "#fff", border: "1px solid #e5e0d5", borderRadius: 12, padding: 16, display: "flex", justifyContent: "space-between", gap: 12 }}>
      <div style={{ minWidth: 0 }}>
        <a href={`/books/${book.id}`} style={{ color: "#1a1a1a", textDecoration: "none" }}>
          <div style={{ fontWeight: 680, fontSize: 15, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{book.title}</div>
          <div style={{ fontSize: 13, color: "#6b6b6b", marginTop: 2 }}>{book.author}</div>
          {book.notes && <div style={{ fontSize: 13, color: "#3a3a3a", marginTop: 8, display: "-webkit-box", WebkitLineClamp: 2, WebkitBoxOrient: "vertical", overflow: "hidden", background: "#fdfcf9", border: "1px solid #f0ebe0", borderRadius: 8, padding: "8px 10px" }}>{book.notes}</div>}
        </a>
      </div>
      {action && <div style={{ flexShrink: 0, alignSelf: "flex-start" }}>{action}</div>}
    </div>
  );
}

export default async function HomePage() {
  const books = await getBooks();
  const reading = books.filter((b) => b.status === "reading");
  const finished = books.filter((b) => b.status === "finished");

  return (
    <div>
      <div style={{ marginBottom: 22 }}>
        <h1 style={{ margin: "0 0 6px", fontSize: 26, letterSpacing: "-0.03em" }}>Your books</h1>
        <p style={{ margin: 0, color: "#6b6b6b", fontSize: 14 }}>{books.length === 0 ? "No books yet — add one below." : `${reading.length} currently reading · ${finished.length} finished`}</p>
      </div>

      <AddBookForm />

      <section style={{ marginBottom: 28 }}>
        <h2 style={{ fontSize: 13, textTransform: "uppercase", letterSpacing: "0.08em", color: "#7a7468", margin: "0 0 10px" }}>Currently reading · {reading.length}</h2>
        {reading.length === 0 ? (
          <div style={emptyStyle}>Nothing in progress. Add a book or move one back to reading.</div>
        ) : (
          <div style={{ display: "grid", gap: 10 }}>
            {reading.map((book) => (
              <BookCard
                key={book.id}
                book={book}
                action={
                  <form action={markFinished}>
                    <input type="hidden" name="id" value={book.id} />
                    <button type="submit" style={primaryBtn}>Mark finished</button>
                  </form>
                }
              />
            ))}
          </div>
        )}
      </section>

      <section>
        <h2 style={{ fontSize: 13, textTransform: "uppercase", letterSpacing: "0.08em", color: "#7a7468", margin: "0 0 10px" }}>Finished · {finished.length}</h2>
        {finished.length === 0 ? (
          <div style={emptyStyle}>No finished books yet.</div>
        ) : (
          <div style={{ display: "grid", gap: 10 }}>
            {finished.map((book) => (
              <BookCard key={book.id} book={book} />
            ))}
          </div>
        )}
      </section>
    </div>
  );
}

const emptyStyle: React.CSSProperties = { background: "#fff", border: "1px dashed #e5e0d5", borderRadius: 12, padding: 16, color: "#7a7468", fontSize: 14 };
const primaryBtn: React.CSSProperties = { background: "#1a1a1a", color: "#fff", border: "1px solid #1a1a1a", borderRadius: 999, padding: "7px 12px", cursor: "pointer", fontSize: 12, fontWeight: 650, whiteSpace: "nowrap" };

