        {book.notes ? (
          <div style={{ background: "#fdfcf9", border: "1px solid #f0ebe0", borderRadius: 10, padding: "12px 14px", whiteSpace: "pre-wrap", fontSize: 14, lineHeight: 1.6 }}>{book.notes}</div>
        ) : (
          <div style={{ color: "#7a7468", fontSize: 14, fontStyle: "italic" }}>No notes yet.</div>
        )}

        <div style={{ marginTop: 18, display: "flex", gap: 8, flexWrap: "wrap" }}>
