            Send someone this link: <a href={sharePath} style={{ color: "#1a1a1a", fontWeight: 600 }}>{sharePath}</a>
          </div>
          <div style={{ fontSize: 12, color: "#7a7468", marginTop: 4 }}>Anyone with the link can view title, author and notes.</div>
        </div>
      </div>
    </div>
  );
}

